            // TODO API_TEST_START
            int origWidth = sourceImage.getWidth();
            int origHeight = sourceImage.getHeight();
            int thumbWidth = origWidth * 2;
            int thumbHeight = origHeight * 2;

            // Let Thumbnailator handle the upscaling condition internally
            java.awt.image.BufferedImage upscaled = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
                .size(thumbWidth, thumbHeight)
                .asBufferedImage();

            // Custom Rename strategy using standard Java 'if' statement as per authoritative usage
            net.coobird.thumbnailator.name.Rename customRename = new net.coobird.thumbnailator.name.Rename() {
                @Override
                public String apply(String name, net.coobird.thumbnailator.ThumbnailParameter param) {
                    if (name.endsWith(".gif")) {
                        return "thumbnail." + name + ".foobar";
                    }
                    return name;
                }
            };

